// Class 6 Social Science practice bank, part 4: Unity in Diversity to Economic Activities Around Us. Extra questions for year-long practice (unreviewed draft).
(function () {
  let n = 4 - 1;
  // M(level, question, right answer, three wrong answers, explanation): the right answer is stored at a varying position.
  function M(level, q, right, wrong, explain) {
    const at = (n++) % 4;
    const options = wrong.slice();
    options.splice(at, 0, right);
    return { q, options, answer: at, explain, level };
  }
  function W(marks, q, a, type) {
    const o = { q, a, marks };
    if (type) o.type = type;
    return o;
  }
  StudyData.addPractice(6, "sst", {
  "unity-in-diversity": {
    mcq: [
      M(1, "Eid is a major festival of", "Muslims", ["Jains", "Parsis", "Buddhists"], "Eid is celebrated by Muslims, and friends of other faiths often share in the joy."),
      M(1, "Which two festivals of the south are named in the lesson?", "Pongal and Onam", ["Baisakhi and Eid", "Christmas and Baisakhi", "Onam and Eid"], "Pongal belongs to Tamil Nadu and Onam to Kerala."),
      M(1, "How many major religions does the lesson list for India?", "Seven", ["Five", "Six", "Eight"], "Hinduism, Islam, Christianity, Sikhism, Buddhism, Jainism and Zoroastrianism make seven."),
      M(1, "A school poster says 'Many languages, many faiths, one country.' The poster is about", "unity in diversity", ["a trade agreement between states", "the history of the Stone Age", "the rules for local elections"], "Unity in diversity means that people with many differences are bound together as one country."),
      M(3, "The Rigveda line 'Ekam sat vipra bahudha vadanti' helps us explain", "why many beliefs can live together", ["why all people must follow a single belief", "why festivals should be stopped by law", "why the wise should never speak to others"], "If truth is one but called by many names, different beliefs can exist side by side."),
      M(1, "The Kumbh Mela draws pilgrims from", "across the country", ["only one village near the river", "only one state of the country", "only one school of the town"], "It is a pilgrimage that brings people from different regions together."),
      M(1, "Christmas is celebrated mainly by", "Christians", ["Buddhists", "Jains", "Parsis"], "Christmas is a major festival of Christians."),
      M(2, "Which festival in the lesson is linked to a community and not to a single state?", "Christmas", ["Pongal", "Onam", "Baisakhi"], "Pongal, Onam and Baisakhi are tied to states; Christmas is celebrated by Christians across the country."),
      M(2, "'Diversity' in India means", "many languages, religions and customs", ["only one language and religion", "a complete absence of any festivals", "people living in a single big city"], "Diversity means variety in languages, religions, customs and ways of life."),
      M(2, "Which of these binds Indians together despite their differences?", "Shared values of the Constitution", ["One language spoken by everyone", "One style of dress for all", "One festival kept by every family"], "Indians share a history, a geography and the values of the Constitution."),
      M(2, "Tolerance means", "respecting different beliefs", ["agreeing with every belief you hear", "leaving the room when others pray", "keeping to your own customs only"], "Tolerance means accepting and respecting beliefs and customs different from our own."),
      M(2, "How does the Kumbh Mela help to unite people?", "Pilgrims from many regions meet", ["It asks everyone to speak Tamil", "It lets only one state take part", "It closes the borders of the states"], "It draws pilgrims from across the country, so people of different regions meet."),
      M(2, "Meeting people of other regions during a pilgrimage helps us to", "learn about their customs", ["forget our own customs", "stop all travel between states", "avoid people who speak differently"], "Pilgrimage connects regions, so people learn about each other's customs."),
      M(2, "Which is NOT a major religion listed in the lesson?", "Taoism", ["Buddhism", "Zoroastrianism", "Jainism"], "The lesson lists Hinduism, Islam, Christianity, Sikhism, Buddhism, Jainism and Zoroastrianism."),
      M(2, "'Many in the One' best matches", "variety within a united nation", ["one language for many states", "many nations in one village", "one religion in many lands"], "India has many languages, religions and customs, yet one shared culture and Constitution."),
      M(2, "What has helped connect people from different regions over centuries?", "Trade and pilgrimage", ["Walls between towns", "Keeping to one's village always", "A ban on travel"], "Trade, pilgrimage and movement of people connected regions."),
      M(2, "Neha's school holds a day where every child brings a dish from home and tells where it is from. This best promotes", "respect for diversity", ["competition for prizes", "one common dress", "separate groups"], "Sharing food from different regions builds respect for diversity."),
      M(2, "Friends celebrating each other's festivals is an example of", "unity in diversity", ["unity without differences", "isolation", "competition"], "Sharing festivals across communities shows unity in diversity."),
      M(1, "In the line 'Ekam sat vipra bahudha vadanti', the 'vipra' are", "the wise", ["the kings", "the farmers", "the traders"], "The line means 'Truth is one; the wise call it by many names'."),
      M(3, "Ravi says all Indians must speak one language to be united. What is a better view?", "Shared values and history, not language", ["Everyone should be made to speak one language", "India has no common ground at all", "Only one single religion can unite the country"], "The lesson says Indians are bound by a common history, geography and the values of the Constitution."),
      M(3, "A neighbour from another state invites your family to a festival you do not celebrate. What is the best response?", "Join in with respect and learn about it", ["Refuse because it is different", "Ask them to stop the festival", "Laugh at their customs"], "Respecting each other's customs and sharing festivals is part of living in a diverse society."),
      M(3, "Which statement shows 'many in the One'?", "Many languages, one Constitution", ["Many constitutions, one language", "One language, one religion", "Many countries, one flag"], "India has many languages and faiths but one Constitution."),
      M(1, "'Truth is one; the wise call it by many names' is from the", "Rigveda", ["Arthashastra", "Constitution", "Sangam poems"], "The line is from the Rigveda."),
      M(3, "Arjun's family is Sikh and his neighbour's family is Muslim. On Baisakhi they visit, and on Eid they share sweets. This shows", "sharing across communities", ["that only family festivals matter", "that festivals should be forbidden", "that only one faith may celebrate"], "Friends share and celebrate each other's festivals."),
      M(2, "Which festival is NOT correctly paired with its region?", "Baisakhi – Kerala", ["Pongal – Tamil Nadu", "Onam – Kerala", "Baisakhi – Punjab"], "Baisakhi is especially a Punjab festival, not Kerala's."),
    ],
    written: [
      W(2, "Give two examples of diversity in India other than language.", "Any two: different religions, clothes, foods, customs and festivals.", "short"),
      W(1, "Name two festivals of India.", "Any two: Pongal, Onam, Baisakhi, Eid, Christmas.", "short"),
      W(2, "Why does the Rigveda line 'Ekam sat vipra bahudha vadanti' matter for living together today?", "It says that truth is one but is called by many names.\nSo people can respect different beliefs and customs and still live as one society.", "short"),
      W(2, "Is it right to say that India has only 22 languages? Explain.", "No. The Eighth Schedule lists 22 languages that the Constitution recognises.\nPeople in India speak many more languages and dialects.", "short"),
      W(2, "Why do we need tolerance in a diverse country?", "People of different faiths and customs live together.\nTolerance means respecting differences, so we can live peacefully.", "short"),
      W(2, "How do festivals bring communities together?", "Festivals and food are often shared across communities.\nFriends celebrate each other's festivals as well as their own.", "short"),
      W(3, "Name three things that bind Indians together.", "A common history.\nA shared geography.\nThe values of the Constitution, such as equality and freedom. (Trade and pilgrimage have also connected people.)", "short"),
      W(4, "Explain how trade and pilgrimage helped connect India's regions. Give an example.", "Trade and pilgrimage brought people from different regions into contact over centuries.\nThey shared goods, ideas and customs.\nThe Kumbh Mela draws pilgrims from across the country.", "long"),
      W(5, "Write a paragraph on 'unity in diversity' in India, with examples of diversity and what binds us together.", "India has many languages (22 in the Eighth Schedule), many religions such as Hinduism, Islam, Christianity, Sikhism, Buddhism, Jainism and Zoroastrianism, and different foods, clothes and festivals such as Pongal, Onam, Baisakhi, Eid and Christmas.\nYet Indians share a common history, a geography and the values of the Constitution. Trade and pilgrimage connected regions.\nRespecting each other's language, faith and customs and sharing festivals keeps the country united.", "long"),
      W(4, "Case study: In Meena's class, children speak Punjabi, Tamil, Bengali and Malayalam at home. On Friday each child brings a dish and teaches the class a greeting in their language.\n(i) What does this activity show about India?\n(ii) Which value does it promote?\n(iii) Why is it good to learn each other's greetings?", "(i) It shows India's diversity of languages and food.\n(ii) It promotes respect for differences, or tolerance.\n(iii) It helps friends feel included and understand each other.", "case"),
    ]
  },
  "family-and-community": {
    mcq: [
      M(1, "A joint family has 2 grandparents, 2 parents, an uncle, an aunt and 3 children. How many people live in the house?", "9", ["7", "8", "10"], "2 + 2 + 1 + 1 + 3 = 9 people."),
      M(1, "A family is a group related by blood, marriage or", "adoption", ["election", "trade", "tax"], "A family is related by blood, marriage or adoption and lives together."),
      M(2, "Which of these groups forms a community because of a shared occupation?", "Weavers of one village", ["Passengers on a train", "Customers in a shop on one day", "Spectators at a one-day match"], "A community may share a place, language, religion, occupation or interest."),
      M(1, "Friends who meet daily to play kabaddi form a community based on", "a shared interest", ["a shared tax bill", "blood relations", "a shared birthday"], "A community may be formed by people who share an interest."),
      M(1, "A society is a large group of people who live together under shared", "rules and institutions", ["coins and notes", "hills and rivers", "crops and seeds"], "A society is a large group of people living together under shared rules and institutions."),
      M(1, "Families together form", "communities", ["islands", "oceans", "plateaus"], "Families come together to form communities."),
      M(1, "Which action shows respect for elders at home?", "Greeting grandparents politely", ["Talking loudly over them", "Asking them not to speak", "Leaving the room when they enter"], "A child's responsibility is to respect elders."),
      M(2, "A boy is kept from school to do housework all day. Which of his rights is being denied?", "His right to education", ["His right to vote", "His right to a salary", "His right to run the home"], "Children have a right to care and education."),
      M(2, "The correct order from small to large is", "Family, community, society, nation", ["Nation, society, community, family", "Community, family, nation, society", "Society, family, community, nation"], "Family → Community → Society → Nation."),
      M(2, "Which of these is NOT a nuclear family?", "Two parents, a child and a grandparent", ["A father living with his two sons", "A mother living with her daughter", "Two parents living with three children"], "A family that also includes a grandparent is a joint family as the lesson describes it."),
      M(2, "Members of a community help each other during", "festivals and emergencies", ["only holidays spent abroad", "only the examination season", "only the election season"], "Community members help in festivals, emergencies and difficult times."),
      M(2, "Which pair shows a right and its matching responsibility?", "Right to education – study well", ["Right to care – ignore elders", "Right to play – skip all study", "Right to food – waste the food"], "Rights and responsibilities go together: a child with a right to education should study well."),
      M(2, "Residents of one colony who meet to solve common problems share mainly", "a place to live", ["a family tree", "a salary", "a school class"], "A community is a group that shares a place, language, religion, occupation or interest."),
      M(1, "Which of these is a family?", "Parents, children and a grandparent at home", ["Strangers sharing one railway coach for a trip", "Shoppers in one market on a Sunday", "Pupils who ride the same school bus"], "A family is a group related by blood, marriage or adoption who live together."),
      M(2, "Which two things does a peaceful society need?", "Fairness and cooperation", ["Winning every argument by force", "Ignoring everyone else's rights", "Keeping away from everyone"], "Living together peacefully needs fairness, respect for others' rights and cooperation."),
      M(1, "Society is made up of", "many communities together", ["only one single family", "only one single person", "only the children of a town"], "Communities together form a society."),
      M(2, "Which pair is correctly matched?", "Joint family – includes uncles and aunts", ["Nuclear family – includes uncles and aunts", "Community – only blood relatives", "Society – only parents"], "A joint family includes grandparents, uncles, aunts and cousins."),
      M(2, "Ria's family has her parents, her brother and her. Her cousin's family has parents, grandparents, an uncle and an aunt. Ria's cousin lives in a", "joint family", ["nuclear family", "school community", "city council"], "A family with grandparents, uncles and aunts is a joint family."),
      M(3, "Why is household work valuable although it is unpaid?", "Others depend on it each day", ["It has no use for anyone", "Machines now do all of it", "It is needed only for guests"], "It lets other family members go to work or school, so it is valuable to the whole family."),
      M(3, "A neighbourhood organises food and shelter after a flood. This shows", "community help in an emergency", ["a quarrel between two families", "a joint family function at home", "the work of a Union minister"], "Members of a community help each other during emergencies."),
      M(2, "Which statement about family roles is correct?", "Each member has a role", ["Only the eldest has any role", "Children have no role at all", "Roles are fixed for every member"], "Each family member has a role, such as providing for the home or helping with chores and studies."),
      M(3, "Which is the best example of a responsibility of a family member?", "Helping with chores and studies", ["Ignoring elders", "Leaving work for others", "Taking away others' belongings"], "Children's roles include helping with chores and studies."),
      M(3, "A community can be formed by people sharing", "an occupation or interest", ["only the same age", "only the same height", "only the same shoes"], "A community may share a place, language, religion, occupation or interest."),
      M(3, "How does a community differ from a family?", "It is bigger than a family", ["It is smaller than a family", "It has only blood relatives", "It can never share a language"], "A community is a larger group sharing something in common, while a family is related and lives together."),
      M(2, "Rahul's family teaches him to share. This shows the family as", "a first teacher of values", ["a place that makes laws", "a bank for savings", "a market for goods"], "The family teaches children their first lessons in care and cooperation."),
    ],
    written: [
      W(2, "Give two examples of ways in which family members help each other.", "Parents provide for the home and care for children.\nChildren help with chores and studies and respect elders.", "short"),
      W(1, "Name one example of a community.", "A village, a neighbourhood, a school or a religious group.", "short"),
      W(2, "Write two features of a joint family.", "Grandparents, uncles, aunts and cousins live together with parents and children.\nIt is also called an extended family.", "short"),
      W(2, "Give two rights and two responsibilities of children in a family.", "Rights: care and education.\nResponsibilities: respect for elders, and helping with chores and studies.", "short"),
      W(2, "How do community members help one another?", "They help each other during festivals, emergencies and difficult times.", "short"),
      W(2, "Arrange in order from small to large: society, family, nation, community.", "Family → community → society → nation.", "short"),
      W(3, "How does a family teach children cooperation? Give two examples.", "Children share chores such as helping to set the table.\nThey learn to care for younger and older members.\nThese first lessons in care and cooperation help them to live in a community.", "short"),
      W(4, "Explain the roles, rights and responsibilities of members in a family.", "Each member has a role, such as a parent providing for the home or a child helping with chores and studies.\nRights and responsibilities go together.\nChildren have a right to care and education, and a responsibility to respect elders.", "long"),
      W(5, "How do families form communities and communities form a society? What does a society need to live peacefully?", "Families come together to form communities, such as a village, a neighbourhood or a school, which share a place, language, religion, occupation or interest.\nCommunities together form a society.\nLiving together peacefully needs fairness, respect for others' rights and cooperation.", "long"),
      W(4, "Case study: When floods hit Gopal's village, neighbours opened their homes to families whose houses were damaged. Gopal's grandmother cooked for everyone, and his cousins helped carry food.\n(i) Which unit of society helped each other here?\n(ii) Why do communities help in emergencies?\n(iii) What value did the children learn?", "(i) The community, a village of neighbours.\n(ii) Members of a community help each other during emergencies and difficult times.\n(iii) Care and cooperation.", "case"),
    ]
  },
  "grassroots-democracy-part-1-governance": {
    mcq: [
      M(1, "Which of these is NOT a feature of a democracy?", "Rulers fixed for ever, with no vote", ["People choose their representatives", "Citizens have equal rights", "Leaders can be held accountable"], "In a democracy, people elect their representatives and can hold them accountable."),
      M(1, "The Zila Parishad is part of which level of government?", "Local", ["Union", "State", "International"], "The Zila Parishad is a rural local body at the district level."),
      M(2, "When a Gram Sabha approves the village budget, this is an example of", "citizens taking part in decisions", ["the Union deciding for villagers", "rulers acting without a vote", "courts making new laws"], "The Gram Sabha lets all adult voters discuss and approve the Gram Panchayat's plans and budget."),
      M(1, "How many tiers does Panchayati Raj have?", "Three", ["Two", "Four", "Five"], "Gram Panchayat, Panchayat Samiti and Zila Parishad."),
      M(1, "Defence is looked after by the", "Union government", ["Gram Sabha", "Gram Panchayat", "Zila Parishad"], "The Union government handles matters like defence and foreign affairs."),
      M(2, "A district wants a plan to link all its blocks with new roads. Which body should coordinate it?", "Zila Parishad", ["Gram Panchayat", "Panchayat Samiti", "Gram Sabha"], "The Zila Parishad works at the district level and coordinates development across the whole district."),
      M(1, "Which government is closest to the people?", "Local government", ["Union government", "State government", "No government"], "Local governments are closest to the people."),
      M(1, "The 73rd Amendment came into force in 1993. How many years had passed by 2023?", "30 years", ["3 years", "13 years", "300 years"], "2023 − 1993 = 30 years."),
      M(1, "A constitutional amendment is", "a formal change to the Constitution", ["the building of a new village", "the result of an election", "a meeting of all the voters"], "The 73rd Amendment changed the Constitution to give status to Panchayati Raj."),
      M(2, "Which came earlier: the 73rd Amendment's coming into force (1993) or the Constitution coming into force (1950)?", "The Constitution", ["The 73rd Amendment", "They were in the same year", "Neither has a year"], "The Constitution came into force in 1950, long before the amendment in 1993."),
      M(2, "Police and public health are looked after mainly by", "state governments", ["the Gram Sabha only", "foreign countries", "no government"], "State governments look after matters like police and public health."),
      M(1, "Foreign affairs is the work of the", "Union government", ["Gram Panchayat", "State government", "Municipal Council"], "The Union government looks after defence and foreign affairs."),
      M(2, "A rural local government manages daily needs such as", "water, roads and cleanliness", ["ships, ports and sea routes", "foreign trade with other lands", "space missions and satellites"], "Local governments handle daily needs such as water, roads and cleanliness."),
      M(2, "The Gram Sabha approves the", "plans and budget of the Gram Panchayat", ["laws for the whole country", "police rules of the state", "defence of the border"], "It discusses village problems and approves the Gram Panchayat's plans and budget."),
      M(2, "Which sequence is correct from village to district?", "Gram Panchayat, Panchayat Samiti, Zila Parishad", ["Zila Parishad, Gram Panchayat, Panchayat Samiti", "Panchayat Samiti, Zila Parishad, Gram Panchayat", "Gram Sabha, Zila Parishad, Panchayat Samiti"], "The tiers are village, block, district."),
      M(2, "Why does democracy work best when it starts at the grassroots?", "People take part where they live", ["Villages make all the laws for India", "Only towns are allowed to have governments", "Voting is not needed in a democracy"], "Democracy begins in villages and towns where people live."),
      M(2, "A village road is full of potholes. Which body should first deal with it?", "The Gram Panchayat", ["The Union government", "The Supreme Court", "A foreign embassy"], "Local government handles daily needs like roads."),
      M(2, "Rani is 17 and her mother is 40, and both live in the village. Who is an adult voter at the Gram Sabha?", "Her mother", ["Rani only", "Both of them", "Neither of them"], "The Gram Sabha is a meeting of adult voters. Rani is not yet an adult."),
      M(3, "Which pair of task and level is correctly matched?", "Defence – Union government", ["Police – Zila Parishad", "Roads of the village – Union government", "Foreign affairs – Gram Sabha"], "The Union handles defence; state handles police; local handles village roads."),
      M(3, "Why do we need local governments when there is a state government?", "They solve nearby daily problems", ["State governments have nothing to do", "Villages never have any problems", "The Union governs each lane"], "Local governments are closest to the people and handle water, roads and cleanliness."),
      M(3, "A Gram Sabha finds that the village school roof leaks. What is the best step?", "Discuss it and ask the Panchayat to fix it", ["Wait silently for the next census", "Ask the Union to rebuild all schools", "Close the school for a year"], "The Gram Sabha discusses village problems and can check the Gram Panchayat's work."),
      M(3, "Which statement about the three levels of government is correct?", "Each level handles different matters", ["Only the Union government governs", "Local bodies conduct foreign affairs", "State governments run the armed forces"], "Defence and foreign affairs are Union matters, police and public health are state matters, and daily needs are local."),
      M(2, "Which tier connects several Gram Panchayats?", "The Panchayat Samiti", ["The Zila Parishad", "The Gram Sabha", "The Union government"], "The Panchayat Samiti works at the block level."),
      M(2, "Villagers want a new classroom for their school. In which order would they most likely take the matter from the nearest body to the farthest?", "Gram Panchayat, Panchayat Samiti, Zila Parishad", ["Zila Parishad, Panchayat Samiti, Gram Panchayat", "Panchayat Samiti, Zila Parishad, Gram Panchayat", "Zila Parishad, Gram Panchayat, Panchayat Samiti"], "The tiers are village, block and district."),
      M(3, "'Grassroots' in democracy refers to", "villages and towns where people live", ["the capital city and its offices only", "the crops that farmers grow in fields", "foreign lands that trade with India"], "Grassroots means the local level, close to ordinary people."),
    ],
    written: [
      W(2, "Why is it said that democracy works best when it starts at the grassroots?", "The grassroots are the villages and towns where people live.\nPeople can take part in decisions about matters that affect them directly.", "short"),
      W(3, "Match each task to the level of government: defence, police, village water supply.", "Defence – Union government.\nPolice – state government.\nVillage water supply – local government (Gram Panchayat).", "short"),
      W(2, "How can the Gram Sabha keep the Gram Panchayat accountable?", "It discusses the yearly plan and budget.\nIt can check the work of the Gram Panchayat and question its members.", "short"),
      W(2, "Name the three tiers of Panchayati Raj.", "Gram Panchayat (village), Panchayat Samiti (block) and Zila Parishad (district).", "short"),
      W(2, "Name two daily needs handled by local governments.", "Any two: water, roads, cleanliness, street lights, drains.", "short"),
      W(2, "What did the 73rd Constitutional Amendment do?", "It gave constitutional status to Panchayati Raj institutions in 1992.\nIt came into force in 1993.", "short"),
      W(3, "The lane lights in a village do not work. List the steps villagers can take.", "They raise the matter at the Gram Sabha.\nThey ask the Gram Panchayat to repair the lights.\nThe Gram Sabha can later check whether the work has been done.", "short"),
      W(4, "Explain how power is shared among the three levels of government.", "India has Union, state and local governments.\nThe Union government looks after defence and foreign affairs.\nState governments look after police and public health.\nLocal governments handle daily needs such as water, roads and cleanliness.", "long"),
      W(5, "Describe Panchayati Raj: its meaning, the 73rd Amendment, the three tiers and the role of the Gram Sabha.", "Panchayati Raj is the system of local self-government in rural India.\nThe 73rd Constitutional Amendment of 1992 gave it constitutional status and came into force in 1993.\nThe three tiers are the Gram Panchayat (village), Panchayat Samiti (block) and Zila Parishad (district).\nThe Gram Sabha, a meeting of all adult voters, discusses village problems and approves the Gram Panchayat's plans and budget.", "long"),
      W(4, "Case study: In Kapurthala village, the water tank is dirty and the lane lights do not work. The villagers call a Gram Sabha. They ask the Gram Panchayat to clean the tank and fix the lights.\n(i) Who attended the Gram Sabha?\n(ii) Which body is asked to do the work?\n(iii) Why is this called grassroots democracy?", "(i) All adult voters of the village.\n(ii) The Gram Panchayat.\n(iii) Because the people themselves discuss and decide matters in the village where they live.", "case"),
    ]
  },
  "grassroots-democracy-part-2-local-government-rural-areas": {
    mcq: [
      M(2, "A Panchayat elected in 2020 serves a full term. When is the next election due?", "In 2025", ["In 2023", "In 2030", "In 2021"], "A Panchayat is elected for five years, so 2020 + 5 = 2025."),
      M(1, "In a Gram Panchayat, a ward is", "a small area of the village", ["a block of the district", "the head of the village", "a type of tax"], "A ward is a small area within a village that elects its own member."),
      M(1, "The voters of a ward in a village elect", "a member of the Gram Panchayat", ["the Prime Minister", "a High Court judge", "an army officer"], "Members of a Gram Panchayat represent different wards and are elected by the voters."),
      M(1, "Out of 30 Panchayat seats, at least how many are reserved for women?", "10", ["3", "15", "20"], "One-third of 30 is 10."),
      M(1, "The Panchayat Samiti works at the", "block level", ["village level", "district level", "state level"], "The Panchayat Samiti works at the block level."),
      M(1, "A small area of a village that elects its own member is a", "ward", ["block", "district", "state"], "A ward is a small area that elects its own member."),
      M(2, "Anil is a 19-year-old village resident whose name is not on the voters' list. Can he vote in the Panchayat election?", "No, he must first be registered as a voter", ["Yes, because every adult can vote without registering", "No, because only landowners can vote", "Yes, because he lives in the village"], "Every adult citizen who is registered as a voter can vote."),
      M(1, "Which of these does a Gram Panchayat look after?", "Drinking water", ["Defence", "Foreign trade", "Space research"], "It looks after cleanliness, drinking water, streets, drains and primary schools."),
      M(2, "A district has five blocks. How many Zila Parishads does the district have?", "One", ["Two", "Five", "Ten"], "The Zila Parishad works at the district level, so a district has one."),
      M(2, "Seats for Scheduled Castes and Scheduled Tribes in Panchayats are reserved", "in proportion to their population", ["equally in every village", "only in towns", "by drawing lots from all voters"], "The reservation follows the share of each group in the population."),
      M(2, "Why are seats reserved in Panchayats for specific groups?", "So that they are sure to be represented", ["To stop other people from voting at all", "To make the elections last much longer", "To give all the power to one single group"], "Reservation sets aside a share of seats so that these groups have a voice."),
      M(2, "Which task fits the Panchayat Samiti?", "Linking the villages of a block", ["Heading a single ward of a village", "Governing a big city with a Mayor", "Running the whole state government"], "The Panchayat Samiti works at the block level and connects several Gram Panchayats."),
      M(1, "Many states have raised the reservation for women in Panchayats to", "50%", ["10%", "25%", "5%"], "The lesson says many states have raised it to 50%."),
      M(2, "Which of these is NOT a work of a Gram Panchayat?", "Making laws for the whole country", ["Keeping the village streets clean", "Maintaining the village drains", "Running the primary school"], "Laws for the whole country are made at the Union level."),
      M(2, "The Gram Sabha has the power to", "check the work of the Gram Panchayat", ["declare a war on another country", "print the currency notes of India", "run the railways of the country"], "It discusses the yearly plan and can check the Gram Panchayat's work."),
      M(2, "How are members of a Gram Panchayat chosen?", "By the voters of their ward", ["By an order of the Union government", "By the choice of the Sarpanch alone", "By drawing lots among all adults"], "Members represent wards and are elected by the village voters."),
      M(1, "In a village of 12 wards, each ward elects one member. How many ward members does the Panchayat have?", "12", ["1", "6", "24"], "One member per ward, so 12 members."),
      M(2, "Which of these is a service from Panchayats?", "Street lights", ["Metro trains", "Airports", "Ports"], "Panchayats manage sanitation, drinking water, roads, street lights, schools and health centres."),
      M(2, "A Panchayat of 18 seats reserves one-third for women. How many seats are NOT reserved for women?", "12", ["6", "9", "15"], "One-third of 18 is 6, so 18 − 6 = 12 seats are open."),
      M(3, "Why is it useful that the Gram Sabha can check the Panchayat's work?", "Villagers can question their members", ["It ends all village elections", "It gives power to one family", "It removes ward members"], "Checking work keeps elected members accountable to the village."),
      M(2, "A Panchayat has 20 seats and 10 are held by women. This is", "more than the one-third minimum", ["less than the one-third minimum", "exactly one-third", "illegal"], "One-third of 20 is about 7, so 10 is more than the minimum."),
      M(3, "Which sequence puts the tiers from smallest area to largest?", "Gram Panchayat, Panchayat Samiti, Zila Parishad", ["Zila Parishad, Panchayat Samiti, Gram Panchayat", "Panchayat Samiti, Gram Panchayat, Zila Parishad", "Gram Panchayat, Zila Parishad, Panchayat Samiti"], "Village, block, district."),
      M(3, "After five years the term of a Panchayat ends. What should happen next?", "A new election is held", ["The Sarpanch rules for ever", "The Union government appoints members", "The Panchayat is closed for ever"], "Panchayats are elected for five years, and then the voters choose again."),
      M(3, "Which statement is correct?", "Women and SC/ST members are assured seats in Panchayats", ["Only men can be members", "Reservation applies only to the Zila Parishad head", "Seats are sold in auction"], "At least one-third seats are reserved for women, and seats for SC and ST."),
      M(3, "Which task would the Zila Parishad handle rather than one Gram Panchayat?", "Coordinating district development", ["Cleaning a single lane in one village", "Repairing one hand pump of a village", "Lighting one street of a ward"], "The Zila Parishad coordinates development across the whole district."),
      M(2, "The Sarpanch is elected by", "the village", ["the Zila Parishad", "the Union government", "the Governor"], "The Sarpanch is the head of the Gram Panchayat, elected by the village."),
    ],
    written: [
      W(2, "List two duties of a Sarpanch.", "The Sarpanch heads the Gram Panchayat.\nHe or she looks after village cleanliness, drinking water, streets, drains and primary schools along with the members.", "short"),
      W(2, "Why do Panchayats hold fresh elections every five years?", "Elections give voters a chance to choose their representatives again.\nThey keep members accountable to the village.", "short"),
      W(2, "What does the Panchayat Samiti do?", "It works at the block level and connects several Gram Panchayats.", "short"),
      W(2, "What is reservation? Who gets reserved seats in Panchayats?", "Reservation is setting aside a share of seats so that certain groups are sure to be represented.\nSeats are reserved for women (at least one-third) and for Scheduled Castes and Scheduled Tribes in proportion to their population.", "short"),
      W(2, "List four services provided by Panchayats.", "Any four: sanitation, drinking water, roads, street lights, schools, health centres, drains.", "short"),
      W(2, "A Panchayat has 15 seats. How many are reserved for women if one-third are reserved?", "15 ÷ 3 = 5.\nSo 5 seats are reserved for women.", "short"),
      W(3, "Why do we hold Panchayat elections after every five years?", "The term of a Panchayat is five years.\nFresh elections let the voters choose their representatives again.\nThis keeps the members accountable to the village.", "short"),
      W(4, "Explain the role of a Sarpanch and of the members of a Gram Panchayat.", "The Sarpanch heads the Gram Panchayat and is elected by the village.\nMembers represent different wards or areas of the village.\nTogether they look after cleanliness, drinking water, streets, drains and primary schools.", "long"),
      W(5, "Describe the three tiers of rural local government and explain who takes part in Panchayat elections.", "The Gram Panchayat is the village-level body, elected for five years and headed by a Sarpanch.\nThe Panchayat Samiti works at the block level and connects several Gram Panchayats.\nThe Zila Parishad works at the district level and coordinates development.\nEvery adult citizen registered as a voter can vote. Seats are reserved for women (at least one-third) and for Scheduled Castes and Scheduled Tribes.", "long"),
      W(4, "Case study: In Rampur, the Gram Panchayat has 9 seats. Three are reserved for women. The Gram Sabha meets and asks the Panchayat why the street lights are not repaired.\n(i) What fraction of seats is reserved for women?\n(ii) Who attends the Gram Sabha?\n(iii) What power of the Gram Sabha is shown here?", "(i) 3 out of 9, which is one-third.\n(ii) All adult voters of the village.\n(iii) The Gram Sabha can check the work of the Gram Panchayat.", "case"),
    ]
  },
  "grassroots-democracy-part-3-local-government-urban-areas": {
    mcq: [
      M(1, "The head of a Municipal Corporation is the", "Mayor", ["Sarpanch", "Governor", "Prime Minister"], "A Municipal Corporation is headed by a Mayor."),
      M(2, "A city has 80 wards, and each ward elects one councillor. How many councillors does its Corporation have?", "80", ["8", "40", "160"], "One councillor from each ward means 80 councillors."),
      M(2, "The 73rd Amendment is to villages as the 74th Amendment is to", "towns and cities", ["the states of India", "the courts of law", "the schools of a city"], "The 73rd Amendment gave status to Panchayati Raj, and the 74th to urban local bodies."),
      M(1, "A big city is governed by a", "Municipal Corporation", ["Nagar Panchayat", "Gram Panchayat", "Zila Parishad"], "A Municipal Corporation governs a big city."),
      M(2, "Public toilets and parks in a city are provided by the", "urban local body", ["Gram Sabha", "Union government", "Zila Parishad"], "Urban local bodies provide parks, public toilets, water supply and more."),
      M(1, "Waste water from homes, shops and factories is called", "sewage", ["a ward", "a tax", "a scale"], "Sewage must be cleaned and carried away."),
      M(1, "A Municipal Council governs a", "smaller town", ["big city", "village only", "state"], "A Municipal Council governs a smaller town."),
      M(2, "Which is the smallest of the three types of urban local bodies?", "Nagar Panchayat", ["Municipal Council", "Municipal Corporation", "Zila Parishad"], "A Nagar Panchayat governs a place changing from a village into a town."),
      M(1, "Councillors elected in 2021 will face the next election in", "2026", ["2024", "2031", "2022"], "Councillors serve for five years: 2021 + 5 = 2026."),
      M(1, "A Municipal Council is headed by a", "Chairperson", ["Mayor", "Sarpanch", "Governor"], "A Municipal Council is headed by a Chairperson or President."),
      M(1, "A city has 30 wards. If one-third of the wards are reserved for women, how many wards are reserved?", "10", ["3", "15", "20"], "One-third of 30 is 10."),
      M(2, "Why is a city divided into wards?", "Each area gets its own representative", ["So that the city can have many mayors", "So that taxes can be avoided", "So that wards can run their own armies"], "Each ward elects one councillor, so every part of the city has a voice."),
      M(2, "Which of these would a Municipal Corporation NOT look after?", "Defence of the border", ["Public parks", "Street lights", "Sewage disposal"], "Defence is a Union matter; the Corporation looks after daily city services."),
      M(2, "Which citizens help an urban body work well?", "Those who pay taxes and report problems", ["Those who litter the public streets", "Those who ignore all ward meetings", "Those who damage the city parks"], "Citizens take part by paying taxes, reporting problems and attending ward meetings."),
      M(2, "Which of these is a rural body, not an urban one?", "Gram Panchayat", ["Municipal Corporation", "Nagar Panchayat", "Municipal Council"], "The Gram Panchayat is for villages."),
      M(2, "Seats in urban local bodies are reserved for", "women, SC and ST", ["only taxpayers", "only shopkeepers", "only retired officers"], "Seats are reserved for women, Scheduled Castes and Scheduled Tribes."),
      M(2, "Citizens can report a broken street light to", "their ward councillor", ["a foreign embassy", "the Supreme Court first", "the Reserve Bank"], "Reporting problems to the councillor is one way citizens take part."),
      M(2, "Which service is NOT typically given by an urban body?", "Defence of the country", ["Public toilets", "Parks", "Street lights"], "Defence is a Union government matter."),
      M(1, "A town of 50 wards has one councillor per ward. How many councillors does it have?", "50", ["5", "25", "100"], "One councillor from each ward means 50."),
      M(3, "How is a Municipal Corporation different from a Nagar Panchayat?", "It serves a much larger population", ["It governs only farm land", "It has no elected members", "It reports to the Gram Sabha"], "A Corporation governs a big city, while a Nagar Panchayat governs a place changing from a village into a town."),
      M(3, "The 73rd Amendment deals with rural bodies. The 74th Amendment deals with", "urban bodies", ["the Supreme Court", "the Reserve Bank", "defence"], "Both amendments are of 1992."),
      M(3, "A lane in a ward has heaps of garbage. What is the best step for citizens?", "Inform the ward councillor", ["Throw it on a neighbour's land", "Wait for the monsoon to wash it", "Burn it in the open lane"], "Citizens take part by reporting problems to their councillor."),
      M(2, "A Mayor is to a Municipal Corporation as a Sarpanch is to a", "Gram Panchayat", ["Zila Parishad", "Municipal Council", "Nagar Panchayat"], "A Sarpanch heads a Gram Panchayat."),
      M(3, "Which statement about a ward is correct?", "A ward elects one councillor", ["A ward elects the Prime Minister", "A ward has no representative at all", "A ward is a part of a Zila Parishad"], "A ward is a small area of a city or town that elects one councillor."),
      M(3, "Which source of money pays for city services, as the lesson suggests?", "Taxes paid by citizens", ["Gifts from foreign tourists", "Money printed by the Gram Sabha", "Fines on visitors only"], "Citizens take part by paying their taxes, which help urban bodies provide services."),
    ],
    written: [
      W(1, "Who heads a Municipal Corporation?", "The Mayor heads a Municipal Corporation.", "short"),
      W(2, "Who elects a councillor and for how many years?", "The voters of a ward elect a councillor.\nThe term is five years.", "short"),
      W(2, "Name the head of each urban local body.", "Nagar Panchayat – elected leader of the Panchayat.\nMunicipal Council – Chairperson or President.\nMunicipal Corporation – Mayor.", "short"),
      W(2, "Why should citizens pay taxes to the local body?", "Taxes help pay for water supply, sewage disposal, garbage collection, street lights and parks.\nWithout them the body could not provide these services.", "short"),
      W(2, "What did the 74th Constitutional Amendment of 1992 do?", "It gave constitutional status to urban local governments.", "short"),
      W(2, "How can citizens take part in urban local government?", "By paying taxes, reporting problems to their councillor and attending ward meetings.", "short"),
      W(2, "What is sewage? Why must it be carried away?", "Sewage is waste water from homes, shops and factories.\nIt must be cleaned and carried away to keep the city healthy.", "short"),
      W(3, "List three ways in which a citizen can help to keep their ward clean.", "Put garbage in the proper bins and do not litter.\nReport problems such as uncollected garbage to the councillor.\nAttend ward meetings and pay taxes.", "short"),
      W(5, "Explain why towns and cities need local government, and describe the three types of urban bodies.", "Towns and cities have large populations and need water supply, sewage, garbage removal, roads and public health services.\nA Nagar Panchayat governs an area changing from a village into a town.\nA Municipal Council governs a smaller town and is headed by a Chairperson or President.\nA Municipal Corporation governs a big city and is headed by a Mayor.\nUrban local government got constitutional status from the 74th Amendment of 1992.", "long"),
      W(4, "Case study: Raj lives in ward 7 of a city. Garbage has not been picked up for a week. He and his neighbours meet their councillor, who promises to take the matter to the Municipal Corporation.\n(i) Whom did they approach?\n(ii) Which body runs the city?\n(iii) Which service was missing?", "(i) Their ward councillor.\n(ii) The Municipal Corporation, headed by the Mayor.\n(iii) Garbage collection.", "case"),
    ]
  },
  "the-value-of-work": {
    mcq: [
      M(1, "Cooking and cleaning at home are examples of", "unpaid work", ["paid work only", "secondary activity", "voluntary tax"], "Household work is often unpaid."),
      M(1, "A teacher's salary is an example of", "paid work", ["unpaid work", "voluntary work", "barter"], "Paid work gives a wage or salary."),
      M(2, "Asha cooks at home, Bhim is a bank clerk, Charu helps at a free medical camp and Dev is a weaver. How many of them do paid work?", "Two", ["One", "Three", "Four"], "Bhim and Dev earn money. Asha's work is unpaid and Charu's is voluntary."),
      M(2, "A mason lifts bricks all day and a clerk checks accounts all day. Who does mainly mental work?", "The clerk", ["The mason", "Both equally", "Neither of them"], "Checking accounts is mainly mental work, while lifting bricks is mainly physical work."),
      M(1, "Sweeping a classroom floor is mainly", "physical work", ["mental work", "tertiary work", "banking work"], "Sweeping uses the body more than the mind."),
      M(1, "A farmer selling crops is doing", "paid work", ["unpaid work", "only voluntary work", "no work"], "Selling crops earns money."),
      M(1, "Which statement is true of honest work?", "Every honest kind of work matters", ["Some honest work is useless", "Only office work counts", "Physical work is shameful"], "No work should be looked down upon."),
      M(1, "Caring for children and elders at home is", "household work", ["a banking service", "a mining activity", "a trade fair"], "Household work includes cooking, cleaning and caring."),
      M(2, "Without household work, family members would find it hard to", "go to work or school", ["buy a new house", "vote in elections", "speak their language"], "Household work lets other family members go to office, school or work."),
      M(2, "Which two things should every employer give workers?", "Fair pay and safe conditions", ["Short breaks and heavy loads", "Free holidays every single week", "Low pay and unsafe machines"], "Fair wages and safe working conditions help workers live with dignity."),
      M(2, "Which pair is correctly matched?", "Carpenter – mainly physical work", ["Doctor – mainly physical work", "Weaver – mainly mental work", "Engineer – mainly physical work"], "Carpenters do mostly physical work; doctors and engineers mostly mental work."),
      M(2, "A mother sews shirts at home for a shop and is paid per shirt. This is", "paid work done at home", ["voluntary work", "unpaid household chores", "not work at all"], "She earns a wage, so it is paid work, even though it is done at home."),
      M(2, "A student who teaches younger children for free after school is doing", "voluntary work", ["paid work", "secondary work", "tertiary banking"], "Voluntary work is for free to help others."),
      M(2, "Which of these is paid work?", "A bus driver's job", ["A mother cooking for her family", "A child helping her grandmother", "A neighbour helping at a free camp"], "A driver earns a wage."),
      M(2, "Why is unpaid household work valuable?", "Others depend on it each day", ["It has no use for anyone", "Machines now do all of it", "It is needed only for guests"], "It is essential to the family even though no wage is paid."),
      M(2, "Which is an example of voluntary work?", "Cleaning a village park for free", ["Working in a bank for salary", "Making clothes in a factory", "Selling vegetables in a shop"], "No pay is taken in voluntary work."),
      M(2, "Which statement is correct?", "Paid and unpaid work both matter", ["Only paid work has any worth", "Unpaid work cannot be called work", "Only mental work is respectable"], "The lesson says all honest work, paid or unpaid, has value."),
      M(1, "Doctors, teachers and engineers mainly do", "mental work", ["physical work", "voluntary work", "unpaid work"], "These jobs use the mind most."),
      M(3, "Meena stays home to cook, clean and look after her grandfather, so that her brothers can attend school and office. What can we say?", "Her work is valuable though unpaid", ["Her work is of no value at all", "She is sitting idle all day", "Her work is a secondary activity only"], "Household work is essential and valuable to the whole family."),
      M(3, "Ravi says only office work is respectable. The lesson would reply that", "no honest work is lowly", ["office work alone deserves respect", "farmers do not really work", "physical labour should be avoided"], "Every honest kind of work contributes to society."),
      M(3, "Which of these jobs is both physical and paid?", "A mason building a wall for wages", ["A child helping at home for free", "A volunteer giving a talk for free", "A grandparent babysitting"], "Masonry is physical and paid."),
      M(3, "Fair wages are important because", "workers can live with dignity", ["work becomes harder to do", "fewer schools get opened", "employers earn more tax"], "Fair wages and safe conditions let workers live with dignity."),
      M(3, "A child helps her grandmother water the garden. This is", "unpaid work for the family", ["a paid government job", "a banking service", "a salaried contract"], "Help at home without a wage is unpaid work."),
      M(2, "The difference between paid work and unpaid work is that paid work", "gives a wage or salary", ["is easier", "is never done at home", "is always mental"], "Unpaid work is done without a wage."),
      M(1, "Which person does mainly mental work?", "An engineer", ["A weaver", "A carpenter", "A farmer digging a field"], "Engineers do mostly mental work."),
    ],
    written: [
      W(1, "What is work?", "Work is any activity done to meet one's own needs or the needs of others.", "short"),
      W(2, "Is cooking for one's family work? Explain.", "Yes. Work is any activity done to meet needs.\nCooking meets the family's needs, though it is unpaid household work.", "short"),
      W(2, "Why do people do voluntary work? Give two reasons.", "To help others in need without expecting pay.\nTo serve the community, for example by cleaning a park or helping at a camp.", "short"),
      W(2, "Why is a doctor's work called mainly mental work? Give one more example of mental work.", "A doctor uses knowledge and thinking to diagnose and treat patients.\nAnother example: a teacher or an engineer.", "short"),
      W(2, "Why is household work valuable?", "It is essential, even though unpaid.\nIt lets other family members go to office, school or work.", "short"),
      W(2, "Why should no honest work be looked down upon?", "Every honest kind of work contributes to society.", "short"),
      W(3, "What may happen if workers are paid less than fair wages and work in unsafe places?", "They cannot live with dignity.\nThey may fall ill or get hurt.\nSo fair wages and safe conditions are needed.", "short"),
      W(4, "Explain the difference between paid, unpaid and voluntary work with examples.", "Paid work gives a wage or salary, such as a teacher's job.\nUnpaid work, like cooking and cleaning at home, is done without a wage.\nVoluntary work is done for free to help others, such as cleaning a park.", "long"),
      W(5, "Why is every kind of work valuable? Discuss household work, physical and mental work.", "Work is any activity done to meet needs. Household work, such as cooking, cleaning and caring for children and elders, is essential even if unpaid, because it lets others go to office, school or work.\nSome work is mainly physical, like weaving and carpentry, and some mainly mental, like teaching, medicine and engineering.\nEvery honest work contributes to society and none should be looked down upon. Fair wages and safe conditions help workers live with dignity.", "long"),
      W(4, "Case study: Suman runs the house, cooks, and looks after her old father-in-law. Her husband works in a bank. Their daughter helps a charity by reading to children without payment.\n(i) Whose work is paid?\n(ii) Which is voluntary work?\n(iii) Why is Suman's work valuable?", "(i) The husband's work in the bank is paid.\n(ii) The daughter's reading for the charity is voluntary.\n(iii) Suman's household work lets other family members go to work and study.", "case"),
    ]
  },
  "economic-activities-around-us": {
    mcq: [
      M(1, "Which of these is NOT a primary activity?", "Stitching clothes in a factory", ["Fishing in rivers and the sea", "Mining coal and iron ore", "Cutting timber in a forest"], "Stitching in a factory is a secondary activity. Fishing, mining and forestry take resources from nature."),
      M(1, "Which of these is a secondary activity?", "Making furniture", ["Fishing in the sea", "Digging coal from a mine", "Teaching in a school"], "Secondary activities change raw materials into finished goods."),
      M(1, "Which of these is a tertiary activity?", "Banking", ["Farming", "Fishing", "Mining"], "Banking is a service."),
      M(2, "A bus conductor, a nurse and a banker all work in the", "tertiary sector", ["primary sector", "secondary sector", "mining sector"], "They all provide services."),
      M(1, "Things we can touch, such as food and clothes, are", "goods", ["services", "wages", "taxes"], "Goods are things we can touch."),
      M(1, "Transport, teaching and medical care are examples of", "services", ["goods", "raw materials", "primary activities"], "Services are work we pay for."),
      M(1, "Rearing animals is a", "primary activity", ["secondary activity", "tertiary activity", "voluntary activity"], "Primary activities include farming, fishing, forestry, mining and animal rearing."),
      M(1, "A haircut at a salon is an example of a", "service", ["good", "raw material", "tax"], "A service is work done for others, for which we pay."),
      M(2, "In the cotton-to-clothes chain, spinning thread in a mill is part of", "the secondary sector", ["the primary sector", "the tertiary sector", "voluntary work"], "Growing cotton is primary; spinning, weaving and stitching are secondary."),
      M(2, "Wheat grains are ground into flour in a flour mill. The mill is a", "secondary activity", ["primary activity", "tertiary activity", "voluntary activity"], "It changes a raw material into a finished good."),
      M(2, "Which of these is a primary activity?", "Mining", ["Banking", "Baking bread in a factory", "Medical care"], "Mining takes resources directly from nature."),
      M(2, "Which pair is correctly matched?", "Teaching – tertiary", ["Mining – tertiary", "Construction – primary", "Fishing – secondary"], "Teaching is a service; mining is primary; construction is secondary."),
      M(2, "A farmer needs bank loans and transport. This shows that", "all three activities depend on each other", ["farming needs nothing at all but land and rain", "banks do not need any farmers as customers", "factories can run without any raw material"], "A connected economy links primary, secondary and tertiary activities."),
      M(2, "A factory making furniture needs wood. The wood comes from a", "primary activity (forestry)", ["tertiary activity (banking)", "secondary activity (stitching)", "voluntary activity"], "Forestry is a primary activity."),
      M(1, "Which of these is a service?", "Medical care", ["Wheat", "Cloth", "Iron ore"], "Medical care is work done for others."),
      M(2, "A shopkeeper selling biscuits is part of the", "tertiary sector", ["primary sector", "secondary sector", "mining sector"], "Trade is a service."),
      M(2, "Each kind of economic activity adds to", "the country's total production", ["only the farmer's own income", "only the factory's building", "nothing in the national economy"], "All three kinds of activity add to the country's total production."),
      M(2, "Factories get their raw materials mainly from", "the primary sector", ["the tertiary sector", "banks alone", "voluntary work"], "Farms, forests and mines supply raw materials such as cotton and ore."),
      M(3, "Look at this table of workers in a town: farmers 40, fishermen 10, factory workers 30, teachers 15, bankers 5. How many are in primary activities?", "50", ["40", "30", "70"], "Farming and fishing are primary: 40 + 10 = 50."),
      M(2, "A town has 40 farmers, 10 fishermen, 30 factory workers, 15 teachers and 5 bankers. How many work in tertiary activities?", "20", ["15", "30", "50"], "Teaching and banking are services: 15 + 5 = 20."),
      M(3, "A town has 40 farmers, 10 fishermen, 30 factory workers, 15 teachers and 5 bankers. The largest group of workers is in", "primary activities", ["secondary activities", "tertiary activities", "voluntary work"], "Primary has 50, secondary 30 and tertiary 20."),
      M(3, "Which pair has one secondary and one tertiary activity?", "Making toys; selling toys", ["Growing wheat; catching fish in rivers", "Mining coal; digging a well in a field", "Cutting trees; planting seeds in rows"], "Making toys is manufacturing (secondary) and selling them is trade (tertiary)."),
      M(3, "Why does the tertiary sector depend on the other two?", "It moves and sells their goods", ["It grows the cotton and wheat", "It digs the coal and iron ore", "It owns every farm and mine"], "Transport, trade and banking help primary and secondary products reach people."),
      M(2, "Which of these is both a good and a raw material?", "Cotton", ["A bank loan", "Teaching", "Medical advice"], "Cotton is a thing and is used to make cloth."),
      M(3, "A baker makes bread from flour and sells it from her shop. Her making of bread is", "a secondary activity", ["a primary activity", "a tertiary activity", "voluntary work"], "Turning flour into bread is manufacturing."),
    ],
    written: [
      W(1, "What are goods? Give an example.", "Goods are things we can touch, such as food and clothes.", "short"),
      W(1, "Name two primary activities.", "Any two: farming, fishing, forestry, mining, animal rearing.", "short"),
      W(2, "What are services? Give two examples.", "Services are work done for others for which we pay.\nExamples: transport, teaching, medical care, banking.", "short"),
      W(2, "What are secondary activities? Give two examples.", "Secondary activities change raw materials into finished goods.\nExamples: manufacturing and construction.", "short"),
      W(2, "Show how cotton becomes clothes in steps.", "Cotton is spun into thread in a mill.\nThe thread is woven into cloth.\nThe cloth is stitched into clothes in a factory.", "short"),
      W(2, "In which sector does a teacher work and in which sector does a fisherman work? Explain.", "A teacher works in the tertiary sector because teaching is a service.\nA fisherman works in the primary sector because fish are taken directly from nature.", "short"),
      W(3, "Classify into primary, secondary and tertiary: mining, bakery, banking, farming, teaching, construction.", "Primary: mining, farming.\nSecondary: bakery (making bread), construction.\nTertiary: banking, teaching.", "short"),
      W(4, "Explain primary, secondary and tertiary activities with two examples each.", "Primary activities take resources directly from nature, e.g. farming and fishing.\nSecondary activities change raw materials into finished goods, e.g. manufacturing and construction.\nTertiary activities are services, e.g. transport and teaching.", "long"),
      W(5, "How do the three kinds of economic activity depend on each other? Use the example of a farmer and a factory.", "A farmer (primary) needs transport and bank loans (tertiary) and sells cotton to a mill.\nA factory (secondary) needs raw materials from farms and mines (primary), and transport and banks (tertiary) to sell its goods.\nTertiary activities depend on the products of the other two.\nEach adds to the country's total production, so the economy is connected.", "long"),
      W(4, "Case study: In a town, 60 people work in farming, 20 in a cloth factory and 30 in shops, banks and schools.\n(i) How many are in primary activities?\n(ii) How many are in tertiary activities?\n(iii) Name the sector of the cloth factory.", "(i) 60 in farming, which is a primary activity.\n(ii) 30 in shops, banks and schools, which are services (tertiary).\n(iii) The cloth factory is a secondary activity.", "case"),
    ]
  },
  });
})();
